package com.xtensus.hrmanagementapi.workflow;
import com.xtensus.hrmanagementapi.domain.entity.*; import com.xtensus.hrmanagementapi.employe.service.CompteEmailService; import com.xtensus.hrmanagementapi.repository.EmailOutboxRepository; import java.time.LocalDateTime; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class EmailOutboxService{
 private final EmailOutboxRepository repository;private final CompteEmailService emails;public EmailOutboxService(EmailOutboxRepository r,CompteEmailService e){repository=r;emails=e;}
 @Transactional public void planifier(Employe e,String sujet,String titre,String texte){if(e==null||e.getEmail()==null)return;EmailOutbox m=new EmailOutbox();m.setDestinataire(e.getEmail());m.setSujet(sujet);m.setContenuHtml(html(e,titre,texte));m.setStatut("EN_ATTENTE");m.setNombreTentatives(0);m.setProchaineTentative(LocalDateTime.now());m.setDateCreation(LocalDateTime.now());repository.save(m);}
 @Scheduled(fixedDelayString="${app.email-outbox.delay-ms:30000}") @Transactional public void envoyer(){for(EmailOutbox m:repository.findTop20ByStatutAndProchaineTentativeLessThanEqualOrderByDateCreationAsc("EN_ATTENTE",LocalDateTime.now())){try{emails.envoyerHtml(m.getDestinataire(),m.getSujet(),m.getContenuHtml());m.setStatut("ENVOYE");m.setDateEnvoi(LocalDateTime.now());m.setDerniereErreur(null);}catch(Exception ex){int n=m.getNombreTentatives()+1;m.setNombreTentatives(n);m.setDerniereErreur(ex.getMessage()==null?"Erreur SMTP":ex.getMessage().substring(0,Math.min(1000,ex.getMessage().length())));m.setStatut(n>=5?"ECHEC":"EN_ATTENTE");m.setProchaineTentative(LocalDateTime.now().plusMinutes(Math.min(60,n*5L)));}repository.save(m);}}
 private String html(Employe e,String titre,String texte){return "<div style='background:#f7f4ef;padding:32px;font-family:Arial;color:#3d3935'><div style='max-width:620px;margin:auto;background:white;border-radius:18px;overflow:hidden;border:1px solid #eadfd3'><div style='padding:26px;background:linear-gradient(135deg,#fff4e8,#ffe0bd)'><b style='color:#bd5a00'>XTENSUS HR</b><h1>"+titre+"</h1></div><div style='padding:28px'><p>Bonjour "+e.getPrenom()+",</p><p>"+texte+"</p><a href='http://localhost:4200/notifications' style='background:#f58220;color:white;text-decoration:none;padding:12px 20px;border-radius:9px'>Ouvrir XTENSUS HR</a></div></div></div>";}
}
